begin;select plan(4);select ok(to_regclass('v_flow_operation_detail')is not null,'MO Flow detail exists');select ok(to_regclass('v_flow_operation_summary')is not null,'MO Flow summary exists');select ok(to_regclass('v_manufacturing_order_progress')is not null,'MO progress exists');select is((select count(*)::int from v_production_flow_routing_reconciliation where stage_code in('DTG_PICKING','DTG_PRINTING','DTG_PUTWALL','DTG_DISPATCH','UP_PICKING','UP_PRINTING','UP_DISPATCH')),7,'required stages exist');select*from finish();rollback;
